import { produce, enablePatches, enableArrayMethods } from "./src/immer";

enablePatches();
enableArrayMethods();

console.log("=== No Mutation After Reorder Tests ===\n");

// Test 1: Just reverse (no element access)
console.log("Test 1: Just reverse (no element access)");
const base1 = [{ v: 1 }, { v: 2 }, { v: 3 }];
const result1 = produce(base1, draft => {
    draft.reverse();
});
console.log("Base:", JSON.stringify(base1));
console.log("Result:", JSON.stringify(result1));
console.log("Same objects?", base1[0] === result1[2] && base1[2] === result1[0]);
console.log();

// Test 2: Just sort (no element access)
console.log("Test 2: Just sort (no element access)");
const base2 = [{ v: 3 }, { v: 1 }, { v: 2 }];
const result2 = produce(base2, draft => {
    draft.sort((a, b) => a.v - b.v);
});
console.log("Base:", JSON.stringify(base2));
console.log("Result:", JSON.stringify(result2));
console.log("Same objects?", base2[1] === result2[0] && base2[2] === result2[1] && base2[0] === result2[2]);
console.log();

// Test 3: Read element but don't modify
console.log("Test 3: Read element but don't modify");
const base3 = [{ v: 1 }, { v: 2 }, { v: 3 }];
const result3 = produce(base3, draft => {
    draft.reverse();
    const firstVal = draft[0].v;
    console.log("  Read draft[0].v:", firstVal);
});
console.log("Base:", JSON.stringify(base3));
console.log("Result:", JSON.stringify(result3));
console.log("Same objects?", base3[0] === result3[2] && base3[2] === result3[0]);
console.log();

// Test 4: Compare with and without array methods plugin
console.log("Test 4: Performance check - proxies created");
const base4 = [{ v: 1 }, { v: 2 }, { v: 3 }, { v: 4 }, { v: 5 }];
let proxyCount4 = 0;
const result4 = produce(base4, draft => {
    draft.reverse();
    // Only access element 0, should only create proxy for element 0
    draft[0].v = 100;
});
console.log("Base:", JSON.stringify(base4));
console.log("Result:", JSON.stringify(result4));
console.log("Only modified element 0, other elements should be same objects");
console.log("base4[1] === result4[3]?", base4[1] === result4[3]);
console.log("base4[2] === result4[2]?", base4[2] === result4[2]);
console.log("base4[3] === result4[1]?", base4[3] === result4[1]);
console.log("base4[4] === result4[0]?", base4[4] === result4[0]);

