import { describe, test, expect } from "vitest";
import { produce, enableArrayMethods, enablePatches, applyPatches } from "../src/immer";

describe("immer regression", () => {
  test("basic produce", () => {
    const base = { a: 1, b: { c: 2 } };
    const next = produce(base, (d) => { d.a = 2; d.b.c = 3; });
    expect(next.a).toBe(2);
    expect(next.b.c).toBe(3);
    expect(base.a).toBe(1);
  });
  test("array push", () => {
    const base = [1,2,3] as number[];
    const next = produce(base, d => { d.push(4); });
    expect(next).toEqual([1,2,3,4]);
    expect(base).toEqual([1,2,3]);
  });
});

describe("array methods reverse/sort mutation fix", () => {
  test("reverse + mutate should not mutate base", () => {
    enableArrayMethods();
    const base = [{ value: 1 }, { value: 2 }, { value: 3 }];
    const result = produce(base, draft => {
      draft.reverse();
      draft[0].value = 999;
    });
    expect(result).toEqual([{ value: 999 }, { value: 2 }, { value: 1 }]);
    expect(base).toEqual([{ value: 1 }, { value: 2 }, { value: 3 }]);
  });

  test("sort + mutate should not mutate base", () => {
    enableArrayMethods();
    const base = [{ value: 3 }, { value: 1 }, { value: 2 }];
    const result = produce(base, draft => {
      draft.sort((a, b) => a.value - b.value);
      draft[0].value = 999;
    });
    expect(result).toEqual([{ value: 999 }, { value: 2 }, { value: 3 }]);
    expect(base).toEqual([{ value: 3 }, { value: 1 }, { value: 2 }]);
  });

  test("reverse + mutate should generate correct patches", () => {
    enableArrayMethods();
    enablePatches();
    const base = [{ value: 1 }, { value: 2 }, { value: 3 }];
    let patches: any[] = [];
    const result = produce(base, draft => {
      draft.reverse();
      draft[0].value = 999;
    }, (p) => {
      patches = p;
    });
    expect(result).toEqual([{ value: 999 }, { value: 2 }, { value: 1 }]);
    const applied = applyPatches(base, patches);
    expect(applied).toEqual(result);
  });

  test("reverse without mutation should reuse same objects", () => {
    enableArrayMethods();
    const base = [{ value: 1 }, { value: 2 }, { value: 3 }];
    const result = produce(base, draft => {
      draft.reverse();
    });
    expect(result).toEqual([{ value: 3 }, { value: 2 }, { value: 1 }]);
    expect(base[0]).toBe(result[2]);
    expect(base[2]).toBe(result[0]);
  });
});

